const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const NICHES=[['Comedy and entertainment','😂'],['Entertainment and cinema','🎬'],['Fashion and styling','👗'],['Beauty and skincare','💄'],['Food and cooking','🍲'],['Travel and tourism','🧳'],['Technology and gadgets','📱'],['AI & generative media','✨'],['Education and learning','📚'],['Coding & careers','💻'],['Gaming and esports','🎮'],['Fitness and sports','🏏'],['Health and wellness','🌿'],['Parenting and family','👨‍👩‍👧'],['Lifestyle and daily vlogs','☀️'],['Music and singing','🎤'],['Dance and choreography','💃'],['Photography and filmmaking','📷'],['Art, craft and DIY','🎨'],['Business and entrepreneurship','📈'],['Finance and personal money','💰'],['Agriculture and rural life','🌾'],['Devotional and spirituality','🪔'],['News and current affairs','🗞️'],['Books and literature','📖'],['Pets and animals','🐾'],['Wedding and events','💍'],['Home decor and interiors','🪴'],['Sustainability and nature','🌱'],['Local businesses and city guides','📍']];
let creators=[], view='home', role=localStorage.getItem('hm_role')||'', saved=new Set(JSON.parse(localStorage.getItem('hm_saved')||'[]')), briefs=JSON.parse(localStorage.getItem('hm_briefs')||'[]'), campaigns=JSON.parse(localStorage.getItem('hm_campaigns')||'[]'), messages=JSON.parse(localStorage.getItem('hm_messages')||'[]'), review=JSON.parse(localStorage.getItem('hm_review')||'{}'), page=1, filters={q:'',niche:'',state:'',platform:'',language:'',status:''}, selectedCompare=[];
const demoBrands=[{name:'Mango Street Cafe',niche:'Food and cooking',budget:45000,goal:'Launch seasonal menu'},{name:'Veda Skin',niche:'Beauty and skincare',budget:75000,goal:'Build product awareness'},{name:'Orbit Mobile',niche:'Technology and gadgets',budget:120000,goal:'Showcase new device'}];
async function init(){try{const r=await fetch('/api/data');if(!r.ok)throw Error('API unavailable');const payload=await r.json();creators=payload.creators||[];review=payload.state?.review||review;saved=new Set(payload.state?.saved||[...saved]);briefs=payload.state?.briefs||briefs;campaigns=payload.state?.campaigns||campaigns;messages=payload.state?.messages||messages;localStorage.setItem('hm_review',JSON.stringify(review));}catch(e){try{const r=await fetch('data/creators.json');creators=await r.json();}catch(_){creators=[];toast('Start the app with npm start so the local JSON API is available.')}}creators=creators.map(c=>({...c,primary_niche:normalizeNiche(c.primary_niche)}));$('#nav-count').textContent=eligibleCreators().length;updateSavedCount();setupRole();render();}
function normalizeNiche(n){return n||'Uncategorized'}function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function title(s){return s.replace(/\b\w/g,m=>m.toUpperCase())}function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2600)}function persist(){localStorage.setItem('hm_saved',JSON.stringify([...saved]));localStorage.setItem('hm_briefs',JSON.stringify(briefs));localStorage.setItem('hm_campaigns',JSON.stringify(campaigns));localStorage.setItem('hm_messages',JSON.stringify(messages));localStorage.setItem('hm_review',JSON.stringify(review));updateSavedCount();fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({saved:[...saved],briefs,campaigns,messages,review})}).catch(()=>{});}function updateSavedCount(){$('#saved-count').textContent=saved.size}
function go(v){if(v==='admin'&&role!=='admin'){toast('Admin panel is available in the Admin demo role.');return;}view=v;page=1;$('#crumb-title').textContent=({home:'Overview',discover:'Discover creators',brandcampaigns:'Brand campaign discovery',categories:'Categories',matching:'HyAI matching',briefs:'Campaign briefs',campaigns:'Campaign manager',shortlist:'Shortlist & compare',messages:'Collaboration inbox',analytics:'Budget & analytics',admin:'Admin & data import'})[v]||'Overview';$('#sidebar')?.classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function verifiedStatus(c){return review[c.creator_id]||c.verification_status||'Needs review'}function profileUrl(c){return c.instagram_url||c.youtube_url||c.other_profile_urls||''}function canVerify(c){return !!profileUrl(c)&&!!c.creator_source_url&&!!c.location_evidence_url&&!!c.language_evidence_url&&['Telangana','Andhra Pradesh'].includes(c.state)&&['Telugu','English','Hindi'].includes(c.content_language)}function isAccepted(c){return verifiedStatus(c)==='Verified'&&canVerify(c)}function eligibleCreators(){return creators.filter(isAccepted)}function followers(c){let n=Number(c.followers_or_subscribers);return n>0?n.toLocaleString('en-IN'):'Not available'}function platform(c){return [c.primary_platform,...(c.youtube_url?['YouTube']:[]),...(c.instagram_url?['Instagram']:[])].filter(Boolean).join(' · ')}function city(c){return [c.city,c.state].filter(x=>x&&x!=='Unknown').join(', ')||'Location unknown'}function initial(c){return (c.creator_name||'C').split(/[ (–-]/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase()}function publicLinks(c){let a=[];if(c.instagram_url)a.push(`<a class="btn btn-outline btn-sm" href="${esc(c.instagram_url)}" target="_blank" rel="noopener">◎ Instagram ↗</a>`);if(c.youtube_url)a.push(`<a class="btn btn-outline btn-sm" href="${esc(c.youtube_url)}" target="_blank" rel="noopener">▶ YouTube ↗</a>`);if(c.other_profile_urls)a.push(`<a class="btn btn-outline btn-sm" href="${esc(c.other_profile_urls.split(/[;, ]/)[0])}" target="_blank" rel="noopener">Other profile ↗</a>`);return a.join('')||'<span class="muted">No profile link</span>'}
function card(c){let savedOn=saved.has(c.creator_id),status=verifiedStatus(c);return `<article class="creator-card"><div class="creator-cover"><div class="creator-symbol">${esc(initial(c))}</div><span class="platform-badge">${esc(c.primary_platform||'Creator')}</span></div><div class="creator-body"><div class="creator-name-line"><div><h3 class="creator-name">${esc(c.creator_name)}</h3><div class="creator-handle">${esc(c.city&&c.city!=='Unknown'?c.city+' · ':'')}${esc(c.creator_type||'Creator')}</div></div><button class="save-btn ${savedOn?'saved':''}" data-save="${esc(c.creator_id)}" title="${savedOn?'Remove saved creator':'Save creator'}">${savedOn?'♥':'♡'}</button></div><div class="tags"><span class="tag">${esc(c.primary_niche)}</span><span class="tag gray">${esc(c.content_language||'Language unknown')}</span></div><div class="creator-meta"><span>♙ ${esc(city(c))}</span><span>◉ ${esc(followers(c))} ${c.audience_metric_type?' '+esc(c.audience_metric_type):''}</span></div><p class="creator-note">${esc(c.research_notes||'Source-linked creator candidate. Review public profile and audience fit before outreach.')}</p><span class="verification ${isAccepted(c)?'verified':''}">${esc(status)}</span><div class="card-actions"><button class="btn btn-primary" data-profile="${esc(c.creator_id)}">View profile</button><button class="btn btn-outline" data-match="${esc(c.creator_id)}">Match ↗</button></div></div></article>`}
function filtered(){return eligibleCreators().filter(c=>{let q=filters.q.toLowerCase();let text=[c.creator_name,c.creator_type,c.primary_niche,c.secondary_niches,c.content_language,c.city,c.state,c.research_notes].join(' ').toLowerCase();return(!q||text.includes(q))&&(!filters.niche||c.primary_niche===filters.niche)&&(!filters.state||c.state===filters.state)&&(!filters.platform||platform(c).toLowerCase().includes(filters.platform.toLowerCase()))&&(!filters.language||(c.content_language||'Unknown')===filters.language)&&(!filters.status||verifiedStatus(c)===filters.status)})}
function header(eyebrow,h,sub,action=''){return `<div class="section-head" style="margin-top:0"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${h}</h1><p class="subtext">${sub}</p></div>${action}</div>`}
function render(){const root=$('#app-content');const views={home:homeView,discover:discoverView,brandcampaigns:brandCampaignsView,categories:categoriesView,matching:matchingView,briefs:briefsView,campaigns:campaignsView,shortlist:shortlistView,messages:messagesView,analytics:analyticsView,admin:adminView};root.innerHTML=(views[view]||homeView)();bindCommon();}
function homeView(){let niches={};creators.forEach(c=>niches[c.primary_niche]=(niches[c.primary_niche]||0)+1);let top=Object.entries(niches).sort((a,b)=>b[1]-a[1]).slice(0,6),needs=creators.filter(c=>!isAccepted(c)).length;let welcome=role==='creator'?'Creator dashboard · manage your profile, portfolio and incoming campaign opportunities.':role==='brand'?'Brand dashboard · discover verified creators, build briefs and plan campaign budgets.':'Admin dashboard · review candidate evidence, import records and manage the dataset.';return `<div class="role-welcome"><div><b>${esc(role.toUpperCase())} WORKSPACE</b><p>${esc(welcome)}</p></div><button class="btn btn-outline btn-sm" id="role-switch-inline">Switch demo role</button></div><section class="hero"><div class="hero-copy"><div class="eyebrow">THE CREATOR-BRAND CONNECTION</div><h1>Find your next <em>creative match.</em></h1><p>Discover source-linked creators, build smarter campaigns, and turn a brief into a collaboration. Built for Telugu creator discovery, with honest data signals.</p><div class="hero-actions"><button class="btn btn-dark" data-go="discover">Explore creators ↗</button><button class="btn btn-outline" data-go="briefs">Create campaign brief +</button></div></div><div class="hero-art"><div class="orbit"></div><div class="hero-tile big">🎬</div><div class="hero-tile small">🎨</div><div class="hero-tile side">📱</div></div></section><div class="stat-grid"><div class="stat-card"><div class="stat-icon">◉</div><div><div class="stat-label">Candidate records (not verified)</div><div class="stat-number">${creators.length}</div><div class="stat-note">Loaded from supplied research</div></div></div><div class="stat-card"><div class="stat-icon green">✓</div><div><div class="stat-label">Fully verified creators</div><div class="stat-number">${eligibleCreators().length}</div><div class="stat-note">Based on review status</div></div></div><div class="stat-card"><div class="stat-icon red">⌕</div><div><div class="stat-label">Need manual review</div><div class="stat-number">${creators.filter(c=>!isAccepted(c)).length}</div><div class="stat-note">Identity, language or location</div></div></div><div class="stat-card"><div class="stat-icon purple">♡</div><div><div class="stat-label">Your shortlist</div><div class="stat-number">${saved.size}</div><div class="stat-note">Saved in this browser</div></div></div></div><div class="section-head"><div><h2>Explore creator categories</h2><p>30 supported niches · counts shown are candidate leads, not verified creators</p></div><button class="btn btn-outline btn-sm" data-go="categories">View all categories ↗</button></div><div class="two-col"><section class="panel"><h3 class="panel-title">Niche snapshot</h3><p class="panel-desc">This batch currently covers a subset of all supported niches.</p><div class="niche-list">${top.map(([n,count])=>`<div class="niche-row"><div class="niche-emoji">${emoji(n)}</div><div><b>${esc(n)}</b><small>${count} candidate${count===1?'':'s'}</small><div class="bar"><span style="width:${Math.max(8,count/Math.max(...top.map(x=>x[1]))*100)}%"></span></div></div></div>`).join('')}</div></section><section class="callout"><div class="ai-orb">✦</div><div class="eyebrow" style="color:#ffcc83">MEET YOUR CAMPAIGN COPILOT</div><h3>Smarter briefs start with HyAI.</h3><p>Turn a rough campaign idea into a structured brief, then see transparent matches based on niche, language, location and platform.</p><button class="btn btn-light" data-go="matching">Open HyAI Studio ↗</button></section></div><div class="section-head"><div><h2>Recently verified creators</h2><p>Only records that pass the evidence gate appear in discovery.</p></div><button class="btn btn-outline btn-sm" data-go="discover">Browse all ${eligibleCreators().length} verified creators ↗</button></div><div class="creator-grid">${eligibleCreators().slice(0,3).map(card).join('')||'<div class="empty"><b>No verified creators yet</b>Qualifying candidates will appear here after an admin confirms profile identity, region, language and evidence. The candidate research queue is available in Admin.</div>'}</div><div class="notice" style="margin-top:18px"><strong>Dataset honesty:</strong> The supplied workbook contains ${creators.length} named candidate records, not 1,000 verified creators. The current report states that primary-profile verification and metric validation remain incomplete. No follower counts have been invented. See Admin & data import for source and review files.</div>`}
function discoverView(){let arr=filtered(),pageSize=9,shown=arr.slice((page-1)*pageSize,page*pageSize),opts=(items,sel,placeholder)=>`<option value="">${placeholder}</option>`+items.map(x=>`<option ${sel===x?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('');return `${header('DISCOVERY','Discover creators','Search the current source-linked batch and inspect each profile’s evidence.','<button class="btn btn-primary" data-go="matching">✧ Find matches</button>')}<div class="toolbar"><div class="search-wrap"><span>⌕</span><input id="search" placeholder="Search name, niche, city, language…" value="${esc(filters.q)}"></div><div class="filters"><select id="f-niche">${opts([...new Set(creators.map(c=>c.primary_niche))].sort(),filters.niche,'All niches')}</select><select id="f-state">${opts([...new Set(creators.map(c=>c.state).filter(s=>s&&s!=='Unknown'))].sort(),filters.state,'All locations')}</select><select id="f-platform">${opts(['Instagram','YouTube','Facebook','ShareChat','Moj','Other'],filters.platform,'All platforms')}</select><select id="f-language">${opts([...new Set(creators.map(c=>c.content_language||'Unknown'))].sort(),filters.language,'All languages')}</select><select id="f-status">${opts([...new Set(creators.map(verifiedStatus))].sort(),filters.status,'All statuses')}</select><button class="btn btn-outline" id="reset-filters">Reset</button></div></div><div class="result-line"><span><b>${arr.length}</b> matching records · page ${page} of ${Math.max(1,Math.ceil(arr.length/pageSize))}</span><span>Counts are from the actual loaded dataset</span></div>${shown.length?`<div class="creator-grid">${shown.map(card).join('')}</div><div class="pagination">${page>1?'<button class="page-btn" data-page="'+(page-1)+'">← Previous</button>':''}${Array.from({length:Math.ceil(arr.length/pageSize)},(_,i)=>`<button class="page-btn ${page===i+1?'active':''}" data-page="${i+1}">${i+1}</button>`).slice(Math.max(0,page-3),page+2).join('')}${page<Math.ceil(arr.length/pageSize)?'<button class="page-btn" data-page="'+(page+1)+'">Next →</button>':''}</div>`:`<div class="empty"><div style="font-size:30px">⌕</div><b>No creators found</b>Try removing a filter or using a broader keyword.<br><button class="btn btn-outline btn-sm" id="empty-reset" style="margin-top:12px">Clear filters</button></div>`}`}
function brandCampaignsView(){return `${header('OPPORTUNITIES','Brand campaign discovery','These are clearly labelled sample opportunities to demonstrate the workflow; they are not live offers.')}<div class="notice"><strong>Demo content:</strong> Brand names, campaign goals and budgets below are illustrative examples, not confirmed advertiser listings or active paid opportunities.</div><div class="creator-grid">${demoBrands.map((b,i)=>`<article class="panel" style="padding:0;overflow:hidden"><div class="creator-cover"><div class="creator-symbol">${['🍽️','✨','📱'][i]}</div><span class="platform-badge">DEMO CAMPAIGN</span></div><div class="creator-body"><div class="eyebrow">${esc(b.niche)}</div><h3 class="creator-name" style="font-size:15px;margin-top:8px">${esc(b.name)}</h3><p class="creator-note" style="margin-top:10px">${esc(b.goal)}. Brief is illustrative and requires brand confirmation.</p><div class="creator-meta"><span>Budget example: ₹${Number(b.budget).toLocaleString('en-IN')}</span></div><button class="btn btn-primary" data-brand-campaign="${i}">Build a brief from this ↗</button></div></article>`).join('')}</div>`}
function categoriesView(){let counts=countNiches();return `${header('BROWSE BY INTEREST','30 creator niches','Select a niche to see eligible verified creators. Candidate counts are available in Admin.')}<div class="notice">The platform supports 30 categories, but the current research batch contains candidates in only ${Object.keys(counts).length} primary niches. Empty categories are ready for future imports; no profiles are fabricated to fill them.</div><div class="category-grid">${NICHES.map(([n,e])=>`<article class="category-card" data-category="${esc(n)}"><div class="category-emoji">${e}</div><h3>${esc(n)}</h3><p>Discover relevant creators and evaluate their public profile evidence.</p><small>${counts[n]||0} candidate${counts[n]===1?'':'s'} · Explore ↗</small></article>`).join('')}</div>`}
function matchingView(){return `${header('HYAI STUDIO','From campaign idea to creator match','Local, explainable matching. No paid AI API or key is used.')}<div class="two-col-equal"><section class="panel"><h3 class="panel-title">Tell HyAI what you need</h3><p class="panel-desc">Enter campaign details; HyAI creates a brief and ranks records using visible matching factors.</p><form id="match-form"><div class="form-grid" style="margin-top:17px"><div class="field full"><label>Campaign idea *</label><textarea id="m-idea" required placeholder="Example: Promote a new cafe menu to Telugu-speaking food lovers in Hyderabad."></textarea></div><div class="field"><label>Preferred niche</label><select id="m-niche"><option value="">Any niche</option>${NICHES.map(([n])=>`<option>${esc(n)}</option>`).join('')}</select></div><div class="field"><label>Target location</label><select id="m-location"><option value="">Any location</option><option>Telangana</option><option>Andhra Pradesh</option><option>Hyderabad</option><option>Vijayawada</option><option>Visakhapatnam</option></select></div><div class="field"><label>Language</label><select id="m-language"><option value="">Any language</option><option>Telugu</option><option>English</option><option>Hindi</option></select></div><div class="field"><label>Platform</label><select id="m-platform"><option value="">Any platform</option><option>Instagram</option><option>YouTube</option><option>Facebook</option><option>ShareChat</option><option>Moj</option><option>Other</option></select></div><div class="field"><label>Budget (₹)</label><input type="number" id="m-budget" min="0" placeholder="e.g. 50000"></div><div class="field"><label>Content format</label><select id="m-format"><option>Any format</option><option>Reel / short video</option><option>YouTube video</option><option>Story</option><option>Static post</option><option>AI-generated video</option><option>Animation / motion graphics</option></select></div></div><div class="form-actions"><button type="reset" class="btn btn-outline">Reset</button><button class="btn btn-primary">Generate local matches ✦</button></div></form></section><section class="panel"><div class="eyebrow">YOUR MATCH RESULTS</div><h3 class="panel-title" style="margin-top:7px">Explainable recommendations</h3><p class="panel-desc">Match score is a rule-based relevance indicator, not a performance prediction.</p><div id="match-results"><div class="empty" style="margin-top:17px"><div style="font-size:27px">✧</div><b>Ready when you are</b>Enter a campaign idea to see creator matches.</div></div></section></div><div class="section-head"><div><h2>What HyAI checks</h2><p>Transparent criteria based on available fields.</p></div></div><div class="metric-grid"><div class="metric-box"><small>Category relevance</small><strong>40%</strong><p>Matches the niche or campaign keywords.</p></div><div class="metric-box"><small>Language fit</small><strong>25%</strong><p>Uses the stated content language when known.</p></div><div class="metric-box"><small>Region + platform</small><strong>35%</strong><p>Uses available location and platform evidence.</p></div></div>`}
function briefsView(){return `${header('CAMPAIGN WORKSPACE','Campaign brief builder','Create a structured brief with deliverables, format, licensing and commercial-use needs.')}<div class="two-col-equal"><section class="panel"><h3 class="panel-title">Build your brief</h3><p class="panel-desc">Saved locally in this browser. No message is sent externally.</p><form id="brief-form"><div class="form-grid" style="margin-top:17px"><div class="field"><label>Brand / agency name *</label><input required name="brand" placeholder="Your brand"></div><div class="field"><label>Campaign title *</label><input required name="title" placeholder="Campaign name"></div><div class="field"><label>Objective *</label><select required name="objective"><option value="">Choose objective</option><option>Awareness</option><option>Product launch</option><option>Engagement</option><option>Traffic / conversions</option><option>App installs</option><option>Community building</option></select></div><div class="field"><label>Preferred niche</label><select name="niche">${NICHES.map(([n])=>`<option>${esc(n)}</option>`).join('')}</select></div><div class="field"><label>Language</label><select name="language"><option>Telugu</option><option>English</option><option>Hindi</option><option>Multilingual</option></select></div><div class="field"><label>Platform</label><select name="platform"><option>Instagram</option><option>YouTube</option><option>Facebook</option><option>ShareChat</option><option>Moj</option><option>Instagram + YouTube</option><option>Any</option></select></div><div class="field"><label>Target state / city</label><input name="location" placeholder="Telangana / Hyderabad"></div><div class="field"><label>Budget (₹) *</label><input name="budget" required type="number" min="0" placeholder="50000"></div><div class="field"><label>Content type</label><select name="contentType"><option>Reel / short video</option><option>YouTube video</option><option>Static post</option><option>Story set</option><option>AI-generated video</option><option>Animation / motion graphics</option><option>Mixed deliverables</option></select></div><div class="field"><label>Aspect ratio / format</label><select name="aspect"><option>9:16 vertical</option><option>16:9 landscape</option><option>1:1 square</option><option>4:5 portrait</option><option>Multiple formats</option></select></div><div class="field"><label>Commercial use</label><select name="commercial"><option>Organic social only</option><option>Paid ads usage required</option><option>Website + social usage</option><option>Whitelisting / creator handle ads</option><option>License to be negotiated</option></select></div><div class="field"><label>Usage duration</label><select name="duration"><option>30 days</option><option>90 days</option><option>6 months</option><option>12 months</option><option>Perpetual license requested</option><option>To be negotiated</option></select></div><div class="field full"><label>Product / campaign context *</label><textarea required name="context" placeholder="What are you promoting? Who is the audience? What should creators communicate?"></textarea></div><div class="field full"><label>Deliverables, style and notes</label><textarea name="notes" placeholder="Number of videos, tone, key messages, revision rounds, usage restrictions…"></textarea></div></div><div class="form-actions"><button type="reset" class="btn btn-outline">Reset form</button><button class="btn btn-primary">Save brief ↗</button></div></form></section><section><div class="panel"><h3 class="panel-title">Saved briefs <span class="tag">${briefs.length}</span></h3><p class="panel-desc">Open, export, or convert a brief into a campaign tracker.</p><div id="brief-list" style="margin-top:15px">${briefList()}</div></div><div class="notice" style="margin-top:14px"><strong>Commercial-use reminder:</strong> Always agree on usage rights, duration, territory, paid media, exclusivity, revisions, and AI disclosure with the creator. This prototype does not provide legal advice.</div></section></div>`}
function briefList(){if(!briefs.length)return '<div class="empty">No briefs saved yet.<b>Create your first brief</b></div>';return briefs.map((b,i)=>`<div class="match-result"><div class="match-score">${i+1}</div><div style="flex:1"><h4>${esc(b.title)}</h4><p>${esc(b.brand)} · ${esc(b.objective)} · ₹${Number(b.budget||0).toLocaleString('en-IN')}</p><p>${esc(b.niche)} · ${esc(b.contentType)} · ${esc(b.aspect)}</p></div><button class="btn btn-outline btn-sm" data-export-brief="${i}">Export</button><button class="btn btn-primary btn-sm" data-campaign-brief="${i}">Track</button><button class="save-btn" data-delete-brief="${i}">×</button></div>`).join('')}
function campaignsView(){return `${header('ENGAGEMENT WORKFLOW','Campaign manager','Track campaign status locally from brief to delivery.')}<div class="hero-mini"><div><div class="eyebrow">CAMPAIGN PIPELINE</div><h2>Keep every collaboration moving.</h2><p>Campaign tracking is local demo data. It does not contact creators or brands.</p></div><button class="btn btn-primary" data-go="briefs">+ Create brief</button></div><div class="stat-grid"><div class="stat-card"><div class="stat-icon">▤</div><div><div class="stat-label">Tracked campaigns</div><div class="stat-number">${campaigns.length}</div></div></div><div class="stat-card"><div class="stat-icon green">✓</div><div><div class="stat-label">Delivered</div><div class="stat-number">${campaigns.filter(c=>c.status==='Delivered').length}</div></div></div><div class="stat-card"><div class="stat-icon red">↻</div><div><div class="stat-label">In progress</div><div class="stat-number">${campaigns.filter(c=>c.status==='In progress').length}</div></div></div><div class="stat-card"><div class="stat-icon purple">◷</div><div><div class="stat-label">Planning</div><div class="stat-number">${campaigns.filter(c=>c.status==='Planning').length}</div></div></div></div><div class="panel" style="margin-top:17px"><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Brand</th><th>Budget</th><th>Status</th><th>Update status</th><th>Action</th></tr></thead><tbody>${campaigns.length?campaigns.map((c,i)=>`<tr><td><strong>${esc(c.title)}</strong><br><span class="muted">${esc(c.niche||'')}</span></td><td>${esc(c.brand)}</td><td>₹${Number(c.budget||0).toLocaleString('en-IN')}</td><td><span class="status ${c.status==='Delivered'?'green':''}">${esc(c.status)}</span></td><td><select data-campaign-status="${i}">${['Planning','Outreach','In progress','Review','Delivered','Paused'].map(s=>`<option ${c.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="btn btn-outline btn-sm" data-campaign-detail="${i}">Details</button> <button class="btn btn-outline btn-sm" data-delete-campaign="${i}">Delete</button></td></tr>`).join(''):'<tr><td colspan="6" class="muted">No campaigns tracked yet. Save a campaign brief and click Track.</td></tr>'}</tbody></table></div></div>`}
function shortlistView(){let arr=eligibleCreators().filter(c=>saved.has(c.creator_id));return `${header('YOUR PICKS','Shortlist & compare','Save profiles from discovery and compare what is actually available.')}<div class="section-head" style="margin-top:0"><div><h2>${arr.length} saved creator${arr.length===1?'':'s'}</h2><p>Saved IDs persist in this browser.</p></div><div><button class="btn btn-outline btn-sm" id="compare-toggle">${selectedCompare.length?'Hide comparison':'Compare selected'}</button> <button class="btn btn-outline btn-sm" id="export-shortlist">Export CSV</button></div></div>${arr.length?`<div class="panel ${selectedCompare.length?'':'hidden'}" id="compare-panel" style="margin-bottom:16px"><h3 class="panel-title">Compare creators</h3><p class="panel-desc">Select up to three profiles using the checkboxes.</p><div class="table-wrap"><table><thead><tr><th>Field</th>${arr.filter(c=>selectedCompare.includes(c.creator_id)).slice(0,3).map(c=>`<th>${esc(c.creator_name)}</th>`).join('')}</tr></thead><tbody>${[['Niche',c=>c.primary_niche],['Language',c=>c.content_language||'Unknown'],['Location',city],['Platform',platform],['Audience',followers],['Status',verifiedStatus],['Source',c=>`<a target="_blank" rel="noopener" href="${esc(c.creator_source_url||'#')}">Open source ↗</a>`]].map(([label,fn])=>`<tr><td><strong>${label}</strong></td>${arr.filter(c=>selectedCompare.includes(c.creator_id)).slice(0,3).map(c=>`<td>${typeof fn(c)==='string'&&fn(c).startsWith('<a')?fn(c):esc(fn(c))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="panel" style="margin-bottom:14px"><div class="pill-list">${arr.map(c=>`<button class="${selectedCompare.includes(c.creator_id)?'active':''}" data-compare="${esc(c.creator_id)}">${selectedCompare.includes(c.creator_id)?'✓ ':''}${esc(c.creator_name)}</button>`).join('')}</div></div><div class="creator-grid">${arr.map(card).join('')}</div>`:`<div class="empty"><div style="font-size:32px">♡</div><b>Your shortlist is empty</b>Save creators from Discover to compare profiles here.<br><button class="btn btn-primary" data-go="discover" style="margin-top:12px">Discover creators</button></div>`}`}
function messagesView(){return `${header('COLLABORATION','Collaboration inbox','A local messaging demo for planning creator outreach. No messages are actually sent.')}<div class="two-col-equal"><section class="panel"><h3 class="panel-title">Draft a collaboration message</h3><p class="panel-desc">Use this to prepare outreach and copy it into your email or social platform.</p><form id="message-form"><div class="form-grid" style="margin-top:16px"><div class="field full"><label>Recipient / creator</label><select name="recipient"><option>Choose a creator</option>${creators.map(c=>`<option>${esc(c.creator_name)}</option>`).join('')}</select></div><div class="field full"><label>Subject</label><input name="subject" required placeholder="Potential brand collaboration"></div><div class="field full"><label>Message</label><textarea name="body" required placeholder="Hi, I’m reaching out about a campaign…"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Save draft</button></div></form></section><section class="panel"><h3 class="panel-title">Saved drafts <span class="tag">${messages.length}</span></h3><div style="margin-top:14px">${messages.length?messages.map((m,i)=>`<div class="match-result"><div class="match-score">✉</div><div style="flex:1"><h4>${esc(m.subject)}</h4><p>To: ${esc(m.recipient)}</p><p>${esc(m.body)}</p></div><button class="btn btn-outline btn-sm" data-copy-message="${i}">Copy</button><button class="save-btn" data-delete-message="${i}">×</button></div>`).join(''):'<div class="empty">No drafts yet.<b>Drafts are stored locally.</b></div>'}</div></section></div>`}
function analyticsView(){let budget=Number(localStorage.getItem('hm_budget')||50000),views=Number(localStorage.getItem('hm_views')||25000),conv=Number(localStorage.getItem('hm_conv')||2.5),cost=Number(localStorage.getItem('hm_revenue')||150000),estRev=views*conv/100*Number(localStorage.getItem('hm_aov')||600),roi=budget?((estRev-budget)/budget*100):0;return `${header('MEASURE & PLAN','Budget & campaign estimator','Change assumptions to estimate reach, conversions and return. This is a planning calculator, not a performance forecast.')}<div class="two-col-equal"><section class="panel"><h3 class="panel-title">Campaign assumptions</h3><p class="panel-desc">These are illustrative inputs you control; not sourced creator metrics.</p><form id="roi-form"><div class="form-grid" style="margin-top:17px"><div class="field"><label>Total campaign budget (₹)</label><input name="budget" type="number" min="0" value="${budget}"></div><div class="field"><label>Estimated views / reach</label><input name="views" type="number" min="0" value="${views}"></div><div class="field"><label>Conversion rate (%)</label><input name="conv" type="number" min="0" step="0.1" value="${conv}"></div><div class="field"><label>Average order value (₹)</label><input name="aov" type="number" min="0" value="${Number(localStorage.getItem('hm_aov')||600)}"></div></div><div class="form-actions"><button class="btn btn-primary">Calculate estimates</button></div></form></section><section class="panel"><h3 class="panel-title">Illustrative projection</h3><p class="panel-desc">Update the assumptions to refresh these figures.</p><div class="metric-grid" style="grid-template-columns:1fr 1fr;margin-top:16px"><div class="metric-box"><small>Estimated conversions</small><strong>${Math.round(views*conv/100).toLocaleString('en-IN')}</strong><p>Views × conversion rate</p></div><div class="metric-box"><small>Estimated revenue</small><strong>₹${Math.round(estRev).toLocaleString('en-IN')}</strong><p>Conversions × average order</p></div><div class="metric-box"><small>Projected ROI</small><strong style="color:${roi>=0?'#16835d':'#d84e3c'}">${roi.toFixed(1)}%</strong><p>(Revenue − budget) / budget</p></div><div class="metric-box"><small>Break-even ROAS</small><strong>${budget? (estRev/budget).toFixed(2)+'×':'—'}</strong><p>Revenue / budget</p></div></div></section></div><div class="notice" style="margin-top:15px"><strong>Important:</strong> Creator audience figures in the current research batch are blank because the supplied research report did not validate current metrics. This calculator uses your assumptions, not hidden or invented creator analytics.</div>`}
function adminView(){let counts={};creators.forEach(c=>counts[c.primary_niche]=(counts[c.primary_niche]||0)+1);let statusCount={};creators.forEach(c=>statusCount[verifiedStatus(c)]=(statusCount[verifiedStatus(c)]||0)+1);return `${header('DATA OPERATIONS','Admin & creator import','Import source-backed records, review evidence and export clean CSV.')}<div class="notice"><strong>Current dataset:</strong> ${creators.length} candidate records from the supplied research files. The attached data-quality report says No records are pre-approved. Candidates must pass the evidence gate before appearing in discovery; current sourced metrics are 0. The 1,000-record target is not met.</div><div class="stat-grid"><div class="stat-card"><div class="stat-icon">▤</div><div><div class="stat-label">Candidate records</div><div class="stat-number">${creators.length}</div></div></div><div class="stat-card"><div class="stat-icon green">✓</div><div><div class="stat-label">Accepted / reviewed</div><div class="stat-number">${eligibleCreators().length}</div></div></div><div class="stat-card"><div class="stat-icon red">⌕</div><div><div class="stat-label">Needs review</div><div class="stat-number">${creators.filter(c=>!isAccepted(c)).length}</div></div></div><div class="stat-card"><div class="stat-icon purple">◎</div><div><div class="stat-label">Niches represented</div><div class="stat-number">${Object.keys(counts).length}/30</div></div></div></div><div class="two-col-equal" style="margin-top:16px"><section class="panel"><h3 class="panel-title">Import creator records</h3><p class="panel-desc">CSV or JSON. Imported rows are saved to this Replit workspace's JSON data file; export a backup before replacing the workspace.</p><div class="admin-upload"><div style="font-size:28px">⇧</div><b>Choose a CSV or JSON file</b><p class="muted" style="font-size:10px">CSV/JSON candidate import. Verified discovery requires profile + source + location + language evidence and supported region/language.</p><input type="file" id="import-file" accept=".csv,.json,text/csv,application/json"></div><div class="form-actions"><button class="btn btn-outline" id="download-template">Download CSV template</button><button class="btn btn-primary" id="export-data">Export current CSV</button></div><div class="divider"></div><h3 class="panel-title">Research files included</h3><p class="panel-desc">See data/ and docs/ in the project ZIP for the master CSV/JSON, source provenance, review queue, niche summary and quality report.</p></section><section class="panel"><h3 class="panel-title">Verification review queue</h3><p class="panel-desc">Review status is persisted by the local Node backend. A Verified record appears in discovery only when all evidence fields pass the eligibility gate.</p><div class="table-wrap" style="margin-top:13px"><table><thead><tr><th>Creator</th><th>Current status</th><th>Review action</th></tr></thead><tbody>${creators.filter(c=>!isAccepted(c)).map(c=>`<tr><td><strong>${esc(c.creator_name)}</strong><br><span class="muted">${esc(c.primary_niche)}</span></td><td><span class="status">${esc(verifiedStatus(c))}</span></td><td><select data-review="${esc(c.creator_id)}"><option value="">Set status…</option>${['Needs review','Source-linked','Profile matched','Region supported','Language supported','Verified','Unavailable'].map(s=>`<option ${verifiedStatus(c)===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div></section></div><div class="section-head"><div><h2>Dataset quality checklist</h2><p>Use before promoting records to campaign-ready status.</p></div></div><div class="panel"><div class="niche-list">${[['Identity','Confirm the name matches the linked profile.'],['Location','Use public evidence for Telangana / Andhra Pradesh.'],['Language','Check recent content, not just a name.'],['Niche','Assign primary + secondary categories from observed content.'],['Metrics','Record source URL and observation date; estimates must be labelled.'],['Deduplication','Merge platforms only when the identity link is credible.']].map(([a,b])=>`<div class="niche-row"><div class="niche-emoji">✓</div><div><b>${a}</b><small>${b}</small></div></div>`).join('')}</div></div>`}
function countNiches(){let x={};eligibleCreators().forEach(c=>x[c.primary_niche]=(x[c.primary_niche]||0)+1);return x}function emoji(n){return (NICHES.find(([name])=>name.toLowerCase()===String(n).toLowerCase())||[])[1]||'✦'}
function bindCommon(){ $$('[data-brand-campaign]').forEach(b=>b.onclick=()=>{const c=demoBrands[Number(b.dataset.brandCampaign)];go('briefs');setTimeout(()=>{const f=$('#brief-form');if(f){f.elements.brand.value=c.name;f.elements.title.value=c.goal;f.elements.objective.value='Awareness';f.elements.niche.value=c.niche;f.elements.budget.value=c.budget;}},40)});$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-save]').forEach(b=>b.onclick=()=>{let id=b.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);persist();render();toast(saved.has(id)?'Creator added to shortlist':'Creator removed from shortlist')});$$('[data-profile]').forEach(b=>b.onclick=()=>profileModal(b.dataset.profile));$$('[data-match]').forEach(b=>b.onclick=()=>{go('matching');setTimeout(()=>{let c=creators.find(x=>x.creator_id===b.dataset.match);$('#m-idea').value=`Find a brand collaboration for ${c?.creator_name||'this creator'} in ${c?.primary_niche||'their niche'}.`;$('#m-niche').value=c?.primary_niche||'';runMatch()},50)});$$('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);render()});$$('[data-category]').forEach(b=>b.onclick=()=>{filters.niche=b.dataset.category;go('discover')});$$('[data-compare]').forEach(b=>b.onclick=()=>{let id=b.dataset.compare;if(selectedCompare.includes(id))selectedCompare=selectedCompare.filter(x=>x!==id);else if(selectedCompare.length<3)selectedCompare.push(id);else toast('Compare up to three creators at a time');render()});$$('[data-export-brief]').forEach(b=>b.onclick=()=>download(`hypermatch-brief-${b.dataset.exportBrief+1}.json`,JSON.stringify(briefs[+b.dataset.exportBrief],null,2),'application/json'));$$('[data-campaign-brief]').forEach(b=>b.onclick=()=>{let brief=briefs[+b.dataset.campaignBrief];campaigns.push({...brief,status:'Planning',createdAt:new Date().toISOString()});persist();go('campaigns');toast('Campaign added to tracker')});$$('[data-delete-brief]').forEach(b=>b.onclick=()=>{briefs.splice(+b.dataset.deleteBrief,1);persist();render()});$$('[data-campaign-status]').forEach(s=>s.onchange=()=>{campaigns[+s.dataset.campaignStatus].status=s.value;persist();render();toast('Campaign status updated')});$$('[data-delete-campaign]').forEach(b=>b.onclick=()=>{campaigns.splice(+b.dataset.deleteCampaign,1);persist();render()});$$('[data-campaign-detail]').forEach(b=>b.onclick=()=>{let c=campaigns[+b.dataset.campaignDetail];modal('Campaign details',`<p><b>${esc(c.title)}</b></p><p>Brand: ${esc(c.brand)}</p><p>Objective: ${esc(c.objective)}</p><p>Budget: ₹${Number(c.budget||0).toLocaleString('en-IN')}</p><p>Notes: ${esc(c.notes||c.context||'—')}</p>`) });$$('[data-copy-message]').forEach(b=>b.onclick=()=>{let m=messages[+b.dataset.copyMessage];copy(`${m.subject}\n\nHi ${m.recipient},\n${m.body}`)});$$('[data-delete-message]').forEach(b=>b.onclick=()=>{messages.splice(+b.dataset.deleteMessage,1);persist();render()});$('#reset-filters')?.addEventListener('click',()=>{filters={q:'',niche:'',state:'',platform:'',language:'',status:''};page=1;render()});$('#empty-reset')?.addEventListener('click',()=>{filters={q:'',niche:'',state:'',platform:'',language:'',status:''};render()});$('#search')?.addEventListener('input',e=>{filters.q=e.target.value;page=1;refreshDiscovery()});[['f-niche','niche'],['f-state','state'],['f-platform','platform'],['f-language','language'],['f-status','status']].forEach(([id,key])=>$('#'+id)?.addEventListener('change',e=>{filters[key]=e.target.value;page=1;refreshDiscovery()}));$('#match-form')?.addEventListener('submit',e=>{e.preventDefault();runMatch()});$('#brief-form')?.addEventListener('submit',e=>{e.preventDefault();let obj=Object.fromEntries(new FormData(e.target).entries());obj.id='BR-'+Date.now();obj.createdAt=new Date().toISOString();briefs.unshift(obj);persist();render();toast('Brief saved locally')});$('#message-form')?.addEventListener('submit',e=>{e.preventDefault();messages.unshift(Object.fromEntries(new FormData(e.target).entries()));persist();render();toast('Draft saved locally')});$('#roi-form')?.addEventListener('submit',e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target).entries());[['budget','hm_budget'],['views','hm_views'],['conv','hm_conv'],['aov','hm_aov']].forEach(([k,key])=>localStorage.setItem(key,Number(f[k]||0)));render()});$('#compare-toggle')?.addEventListener('click',()=>{$('#compare-panel')?.classList.toggle('hidden')});$('#export-shortlist')?.addEventListener('click',()=>exportCSV(creators.filter(c=>saved.has(c.creator_id)),'hypermatch-shortlist.csv'));$('#export-data')?.addEventListener('click',()=>exportCSV(creators,'hypermatch-creators-current.csv'));$('#download-template')?.addEventListener('click',()=>download('hypermatch-creator-import-template.csv','creator_id,creator_name,creator_type,primary_platform,youtube_url,instagram_url,other_profile_urls,primary_niche,secondary_niches,content_language,state,city,followers_or_subscribers,audience_metric_type,engagement_rate,engagement_method,metric_source_url,metric_observed_date,creator_source_url,location_evidence_url,language_evidence_url,contact_business_url,verification_status,data_confidence,research_notes\n','text/csv'));$('#import-file')?.addEventListener('change',importFile);$$('[data-review]').forEach(s=>s.onchange=()=>{if(s.value){const c=creators.find(x=>x.creator_id===s.dataset.review);if(s.value==='Verified'&&c&&!canVerify(c)){s.value=verifiedStatus(c);toast('Cannot verify yet: add public profile, source, location evidence, language evidence, supported state and supported language.');return;}review[s.dataset.review]=s.value;persist();$('#nav-count').textContent=eligibleCreators().length;render();toast('Review status saved to project data')}});$('#notification')?.addEventListener('click',()=>toast('You’re all caught up.'))}
function refreshDiscovery(){const active=document.activeElement;const pos=active&&active.id==='search'?active.selectionStart:null;$('#app-content').innerHTML=discoverView();bindCommon();const next=$('#search');if(next){next.focus();if(pos!==null)next.setSelectionRange(pos,pos)}}function profileModal(id){let c=creators.find(x=>x.creator_id===id);if(!c)return;modal('Creator profile',`<div class="creator-name-line"><div class="creator-symbol" style="width:60px;height:60px">${esc(initial(c))}</div><div style="flex:1"><h3 class="creator-name" style="font-size:17px">${esc(c.creator_name)}</h3><p class="muted" style="font-size:11px">${esc(c.creator_type||'Creator')} · ${esc(city(c))}</p><span class="verification ${isAccepted(c)?'verified':''}">${esc(verifiedStatus(c))}</span></div></div><div class="tags"><span class="tag">${esc(c.primary_niche)}</span><span class="tag gray">${esc(c.content_language||'Unknown language')}</span><span class="tag gray">${esc(c.primary_platform||'Platform unknown')}</span></div><div class="divider"></div><div class="metric-grid" style="grid-template-columns:repeat(2,1fr)"><div class="metric-box"><small>Followers / subscribers</small><strong style="font-size:17px">${esc(followers(c))}</strong><p>No current sourced metric in this batch.</p></div><div class="metric-box"><small>Engagement rate</small><strong style="font-size:17px">${c.engagement_rate?esc(c.engagement_rate):'Not available'}</strong><p>Not estimated without post-level evidence.</p></div></div><p style="font-size:11px;line-height:1.7;color:#766b60;margin-top:15px">${esc(c.research_notes||'No additional research notes.')}</p><p style="font-size:10px;color:#8e8275">Evidence: <a href="${esc(c.creator_source_url||'#')}" target="_blank" rel="noopener">Creator profile/source ↗</a>${c.location_evidence_url?` · <a href="${esc(c.location_evidence_url)}" target="_blank" rel="noopener">Location evidence ↗</a>`:''}${c.language_evidence_url?` · <a href="${esc(c.language_evidence_url)}" target="_blank" rel="noopener">Language evidence ↗</a>`:''}</p><div class="card-actions">${publicLinks(c)}<button class="btn btn-outline" data-profile-assist="${esc(c.creator_id)}">Ask profile assistant ✦</button><button class="btn btn-primary" data-modal-save="${esc(c.creator_id)}">${saved.has(c.creator_id)?'♥ Saved':'♡ Save creator'}</button></div>`);$('#modal-root [data-profile-assist]')?.addEventListener('click',()=>{const fit=`HyAI profile assistant (local rules only)\n\n${c.creator_name} is listed under ${c.primary_niche||'an unclassified niche'}, with stated language ${c.content_language||'unknown'} and location ${city(c)}. Current audience metrics: ${followers(c)}.\n\nSuggested next checks: confirm recent content, audience geography, current follower/subscriber count, engagement from recent posts, brand-safety fit and commercial usage rights.\n\nThis is a field-based helper summary, not an external AI assessment or endorsement.`;modal('HyAI profile assistant',`<div class="notice">Local no-key assistant · generated from this profile’s available fields only.</div><p style="white-space:pre-line;line-height:1.7;font-size:12px">${esc(fit)}</p><button class="btn btn-primary" id="copy-profile-assist">Copy assistant notes</button>`);$('#copy-profile-assist')?.addEventListener('click',()=>copy(fit))});$('#modal-root [data-modal-save]')?.addEventListener('click',()=>{saved.has(id)?saved.delete(id):saved.add(id);persist();closeModal();render();toast(saved.has(id)?'Creator saved':'Creator removed')})}
function modal(titleText,body){$('#modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal"><div class="modal-head"><h2>${titleText}</h2><button class="modal-close" id="close-modal">×</button></div>${body}</div></div>`;$('#close-modal').onclick=closeModal;$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')closeModal()}}
function closeModal(){$('#modal-root').innerHTML=''}function runMatch(){let idea=($('#m-idea')?.value||'').toLowerCase(),niche=$('#m-niche')?.value||'',loc=$('#m-location')?.value||'',lang=$('#m-language')?.value||'',plat=$('#m-platform')?.value||'';let words=idea.split(/\W+/).filter(w=>w.length>3);let pool=eligibleCreators();let scored=pool.map(c=>{let score=20,why=[];let cn=c.primary_niche.toLowerCase();if(niche&&cn===niche.toLowerCase()){score+=40;why.push('niche match')}else if(words.some(w=>cn.includes(w)||w.includes(cn.split(' ')[0]))){score+=22;why.push('campaign keyword relevance')}if(lang&&(c.content_language||'').toLowerCase()===lang.toLowerCase()){score+=25;why.push('language match')}else if(lang&&c.content_language==='Unknown'){score+=0;why.push('language needs review')}if(loc&&(c.state||'').toLowerCase().includes(loc.toLowerCase())||(loc==='Hyderabad'&&(c.city||'').toLowerCase()===loc.toLowerCase())){score+=20;why.push('location match')}if(plat&&platform(c).toLowerCase().includes(plat.toLowerCase())){score+=15;why.push('platform match')}if(!niche&&!lang&&!loc&&!plat&&words.some(w=>[c.creator_name,c.primary_niche,c.research_notes].join(' ').toLowerCase().includes(w))){score+=10;why.push('idea keyword match')}return {c,score:Math.min(99,score),why}}).sort((a,b)=>b.score-a.score).slice(0,5);$('#match-results').innerHTML=(scored.length?scored.map(x=>`<div class="match-result"><div class="match-score">${x.score}%</div><div style="flex:1;min-width:120px"><h4>${esc(x.c.creator_name)}</h4><p>${esc(x.c.primary_niche)} · ${esc(city(x.c))}</p><p>${esc(x.why.join(' · ')||'General candidate')} · Status: ${esc(verifiedStatus(x.c))}</p></div><button class="btn btn-outline btn-sm" data-profile="${esc(x.c.creator_id)}">Profile</button><button class="btn btn-primary btn-sm" data-save="${esc(x.c.creator_id)}">+ Save</button></div>`).join(''):`<div class="empty"><b>No eligible creators to match yet</b>HyAI only ranks verified profiles. Review candidates in Admin and approve records after checking the required evidence.</div>`)+`<p class="muted" style="font-size:10px;margin-top:13px">Scores are rule-based, derived from available fields, and are not a forecast of reach, conversions or creator quality.</p>`;$$('#match-results [data-profile]').forEach(b=>b.onclick=()=>profileModal(b.dataset.profile));$$('#match-results [data-save]').forEach(b=>b.onclick=()=>{saved.add(b.dataset.save);persist();render();toast('Creator saved to shortlist')})}
function download(name,data,type){const blob=new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}function csvEscape(v){let s=v==null?'':String(v);return '"'+s.replace(/"/g,'""')+'"'}function exportCSV(rows,name){if(!rows.length){toast('No records to export');return}let cols=Object.keys(rows[0]),csv=[cols.map(csvEscape).join(','),...rows.map(r=>cols.map(c=>csvEscape(r[c])).join(','))].join('\r\n');download(name,'\ufeff'+csv,'text/csv;charset=utf-8');toast('CSV export prepared')}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++}else if(c==='"'){quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(cell.length||row.length){row.push(cell);rows.push(row)}let head=(rows.shift()||[]).map(x=>x.replace(/^\ufeff/,''));return rows.map(r=>Object.fromEntries(head.map((h,i)=>[h,r[i]||''])))}async function importFile(e){let file=e.target.files[0];if(!file)return;try{let text=await file.text(),incoming=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):parseCSV(text);if(!Array.isArray(incoming))throw Error('JSON must contain an array of creator records.');let seen=new Set(creators.map(c=>(profileUrl(c)||c.creator_id||c.creator_name).toLowerCase().trim()));let added=0;incoming.forEach((c,i)=>{if(!c.creator_name)return;let key=(c.instagram_url||c.youtube_url||c.other_profile_urls||c.creator_id||c.creator_name).toLowerCase().trim();if(seen.has(key))return;seen.add(key);creators.push({...c,creator_id:c.creator_id||'IMP-'+Date.now()+'-'+i,primary_niche:c.primary_niche||'Uncategorized',verification_status:c.verification_status||'Needs review',research_notes:c.research_notes||'Imported locally; verify identity, location, language, and profile before campaign use.'});added++});if(added===0)toast('No new records added. Check columns and duplicate profile links.');else{persist();fetch('/api/candidates',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creators})}).then(r=>{if(!r.ok)throw Error('save failed');return r.json()}).then(()=>toast(`${added} candidate record(s) saved to project data`)).catch(()=>toast('Imported in this session; backend save failed'));$('#nav-count').textContent=eligibleCreators().length;render();} }catch(err){toast('Import failed: '+err.message)}e.target.value=''}function copy(s){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(s).then(()=>toast('Copied to clipboard')).catch(()=>{download('hypermatch-message.txt',s,'text/plain');toast('Downloaded message draft instead')});else{download('hypermatch-message.txt',s,'text/plain');toast('Downloaded message draft')}}

function setupRole(){const screen=$('#login-screen');if(!screen)return;if(role){screen.classList.add('hidden');document.body.dataset.role=role;const label=$('#role-label');if(label)label.textContent=role[0].toUpperCase()+role.slice(1);const mini=$('#profile-role');if(mini)mini.textContent=role[0].toUpperCase()+role.slice(1)+' demo';}else screen.classList.remove('hidden');}
function chooseRole(next){role=next;localStorage.setItem('hm_role',role);setupRole();render();toast('Signed in to '+role+' demo workspace');}

$('#login-screen')?.addEventListener('click',e=>{const b=e.target.closest('[data-role-login]');if(b)chooseRole(b.dataset.roleLogin)});$('#role-switch')?.addEventListener('click',()=>{role='';localStorage.removeItem('hm_role');setupRole()});document.addEventListener('click',e=>{if(e.target.closest('#role-switch-inline')){role='';localStorage.removeItem('hm_role');setupRole();}});
$('#nav').addEventListener('click',e=>{let b=e.target.closest('[data-view]');if(b){go(b.dataset.view);$$('.nav-item').forEach(x=>x.classList.toggle('active',x===b));$('#sidebar').classList.remove('open')}});$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));document.addEventListener('click',e=>{let b=e.target.closest('[data-go]');if(b){$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===b.dataset.go))}});init();
